Translate("ruRU", "druids-of-the-fang", {
	title = "Друиды Клыка",
	aliases = { "Друид Клыка", "повелители Клыка", "повелитель Клыка" },
	sections = {
		{
			title = "Обзор",
			text = [=[Друиды Клыка — оскверненные последователи {link:naralex}Наралекс{/link}а. Они пришли в {link:wailing-caverns}Пещеры Стенаний{/link} как орден благородных друидов, намереваясь исцелить {link:burning-steppes}Степи{/link}. Когда сон их наставника стал кошмаром, большинство из них пало вместе с ним. Теперь они носят чешуйчатые лица и змеиные обличья и стремятся переделать землю по образу своих искаженных снов.]=],
		},
		{
			title = "Орден",
			text = [=[Ими повелевают четверо предводителей, повелители Клыка: леди {link:lady-anacondra}Анакондра{/link}, лорд {link:lord-cobrahn}Кобран{/link}, лорд {link:lord-pythas}Питас{/link} и их глава, лорд {link:lord-serpentis}Серпентис{/link}. Каждый владеет самоцветом сна. Под их началом друиды Клыка держат при себе искаженных змей и ящеров, а некоторые ходят по равнинам наверху. Одного из них, по имени Боан, видели возле холма пещер. Немногие ученики, сохранившие рассудок, — среди них Налпак, Эбру и Ученик, что ждет внутри, — трудятся теперь против своих павших братьев.]=],
		},
		{
			title = "Что видели друиды",
			text = [=[{link:hamuul-runetotem}Хамуул Рунический Тотем{/link} вошел в сновидение, чтобы узнать, что отравляет {link:burning-steppes}Степи{/link}. Он увидел секту друидов, чьи цели когда-то были благородны и которые сбились с пути, служа порче, что сочится по земле. Он был стар и не мог оставаться долго. {link:nara-wildmane}Нара Буйногривая{/link} осталась и увидела их лица. Она говорит, что они преследуют ее до сих пор.]=],
		},
	},
})
